import{_ as t,o as l,c as e,a2 as i}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"推荐本地模型","description":"按显存推荐本地大模型（验证通路、角色扮演、中文）；适用于 Ollama、LM Studio、KoboldCPP、llama.cpp 接 MiniTavern。","frontmatter":{"title":"推荐本地模型","description":"按显存推荐本地大模型（验证通路、角色扮演、中文）；适用于 Ollama、LM Studio、KoboldCPP、llama.cpp 接 MiniTavern。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"推荐本地模型 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"按显存推荐本地大模型（验证通路、角色扮演、中文）；适用于 Ollama、LM Studio、KoboldCPP、llama.cpp 接 MiniTavern。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/local/models"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/local/models"}]]},"headers":[],"relativePath":"local/models.md","filePath":"local/models.md","lastUpdated":1787117554000}'),o={name:"local/models.md"};function n(r,a,d,s,h,p){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="推荐模型" tabindex="-1">推荐模型 <a class="header-anchor" href="#推荐模型" aria-label="Permalink to &quot;推荐模型&quot;">​</a></h1><p>模型名与下载方式因工具而异；下表给出 <strong>体量与用途</strong> 建议。具体 pull / 文件名以各工具页面为准。</p><h2 id="按硬件选体量" tabindex="-1">按硬件选体量 <a class="header-anchor" href="#按硬件选体量" aria-label="Permalink to &quot;按硬件选体量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>大致规模</th><th>内存/显存粗略参考</th><th>适合</th></tr></thead><tbody><tr><td>1B–3B</td><td>约 4–8GB</td><td><strong>先验证通路</strong>、低配机器</td></tr><tr><td>7B–9B</td><td>约 8–16GB</td><td>角色扮演常用甜点区</td></tr><tr><td>12B–14B</td><td>16GB+</td><td>质量更好，速度看显卡</td></tr><tr><td>32B+</td><td>24GB+ 或大力量化</td><td>高配；手机连着也会等更久</td></tr></tbody></table><p>量化（Q4 / Q5 / IQ 等）越小越省资源、质量略降。GGUF 用户优先选社区常用的 <code>Q4_K_M</code> / <code>Q5_K_M</code>。</p><h2 id="验证通路-优先小模型" tabindex="-1">验证通路（优先小模型） <a class="header-anchor" href="#验证通路-优先小模型" aria-label="Permalink to &quot;验证通路（优先小模型）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>Ollama 示例</th><th>GGUF / 其它</th></tr></thead><tbody><tr><td>最快测通</td><td><code>llama3.2:3b</code>、<code>qwen2.5:3b</code></td><td>任意 3B 级 instruct GGUF</td></tr><tr><td>中文轻量</td><td><code>qwen2.5:3b</code> / <code>qwen2.5:7b</code></td><td>Qwen2.5 Instruct 量化</td></tr></tbody></table><p>先保证 <a href="/ultra_guides/connect-app/minitavern">测连成功</a>，再换大模型。</p><h2 id="角色扮演向提示" tabindex="-1">角色扮演向提示 <a class="header-anchor" href="#角色扮演向提示" aria-label="Permalink to &quot;角色扮演向提示&quot;">​</a></h2><ul><li>优先 <strong>Instruct / Chat</strong> 微调，而不是纯基座补全模型。</li><li>社区常讨论的 RP 向权重会随时间变化；以你工具内能稳定加载、且上下文长度够用为准。</li><li>上下文（context）太小会导致长设定/世界书截断；7B 级可先从 4k–8k 试起，再按显存加大。</li><li>在 MiniTavern 填写的 <strong>模型名</strong> 必须与工具列表中的名称 <strong>完全一致</strong>（含 tag，如 <code>:7b</code>）。</li></ul><h2 id="ollama-常用拉取示例" tabindex="-1">Ollama 常用拉取示例 <a class="header-anchor" href="#ollama-常用拉取示例" aria-label="Permalink to &quot;Ollama 常用拉取示例&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:14b</span></span></code></pre></div><p>更多命令见 <a href="/ultra_guides/ollama/models">Ollama · 下载与选择模型</a>。</p><h2 id="lm-studio-koboldcpp-llama-cpp" tabindex="-1">LM Studio / KoboldCPP / llama.cpp <a class="header-anchor" href="#lm-studio-koboldcpp-llama-cpp" aria-label="Permalink to &quot;LM Studio / KoboldCPP / llama.cpp&quot;">​</a></h2><ol><li>在 <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> 等来源下载 <strong>GGUF</strong>（注意许可证与来源可信）。</li><li>在对应工具中加载同一文件。</li><li>打开 API / Server 后，把界面显示的 <strong>model id</strong> 抄到 MiniTavern。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./tools">工具总览</a> → 选定工具的「开服务」章节 → <a href="/ultra_guides/connect-app/minitavern">在 MiniTavern 中配置</a></p>`,17)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
